// In Orders module: publishes an event when an order is placed
public record OrderPlacedEvent(Guid OrderId, Guid CustomerId, decimal Total) : INotification;

public class OrderPlacedHandler : INotificationHandler<OrderPlacedEvent>
{
    private readonly IEmailService _emailService;

    public OrderPlacedHandler(IEmailService emailService)
    {
        _emailService = emailService;
    }

    public async Task Handle(OrderPlacedEvent notification, CancellationToken ct)
    {
        await _emailService.SendOrderConfirmationAsync(
            notification.CustomerId, notification.OrderId, ct);
    }
}

